mapper.select:
SELECT id, account_code, account_name, third_party_system, account_type,
       account_identifier, api_key, connection_status, is_enabled, org_id,
       create_user, update_user
FROM TBL_TREASURY_THIRD_PARTY_ACCOUNT


        AND account_code LIKE CONCAT('%', #{params.accountCode}, '%')


        AND account_name LIKE CONCAT('%', #{params.accountName}, '%')


        AND third_party_system = #{params.thirdPartySystem}


        AND account_type = #{params.accountType}


        AND connection_status = #{params.connectionStatus}


ORDER BY id DESC

